class Solution {
  public int minOperations(String s) {
    int n = s.length();
    boolean sorted = true;
    char min = 'z', max = 'a';
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      if (i > 0 && c < s.charAt(i - 1)) sorted = false;
      min = (char) Math.min(min, c);
      max = (char) Math.max(max, c);
    }
    if (sorted) return 0;
    if (n == 2) return -1;
    if (s.charAt(0) == min || s.charAt(n - 1) == max) return 1;
    // two operations fail only when the first char is strictly the largest and the last strictly
    // the smallest
    char firstChar = s.charAt(0), lastChar = s.charAt(n - 1);
    boolean firstStrictMax = true, lastStrictMin = true;
    for (int i = 1; i < n; i++) if (s.charAt(i) >= firstChar) firstStrictMax = false;
    for (int i = 0; i + 1 < n; i++) if (s.charAt(i) <= lastChar) lastStrictMin = false;
    return firstStrictMax && lastStrictMin ? 3 : 2;
  }
}
